CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,organization TEXT,position TEXT,role TEXT NOT NULL DEFAULT 'VIEWER' CHECK(role IN ('ADMIN','OPERATOR','VIEWER')),status TEXT NOT NULL DEFAULT 'INVITED' CHECK(status IN ('INVITED','ACTIVE','DISABLED')),approved_at TEXT,last_login_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);CREATE TABLE IF NOT EXISTS invitations (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL COLLATE NOCASE,user_id TEXT NOT NULL,invited_by TEXT,status TEXT NOT NULL DEFAULT 'PENDING',expires_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS login_audit (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,email TEXT,result TEXT NOT NULL,path TEXT,ip_hash TEXT,user_agent TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_login_audit_created ON login_audit(created_at DESC);